const safeStorage={get(k){try{return localStorage.getItem(k)}catch(e){return null}},set(k,v){try{localStorage.setItem(k,v)}catch(e){}}};
let currentChapter = 0, currentStep = 0, showingHome = true, lastFocus = null, printState = [];
const homePage=document.getElementById('homePage');
const chapterEls=[...document.querySelectorAll('.chapter-v9')];
const desktopNav=document.getElementById('desktopNav');
const drawerNav=document.getElementById('drawerNav');
const stepList=document.getElementById('stepList');
const sidebar=document.getElementById('courseSidebar');
const drawer=document.getElementById('mobileDrawer');
const menuTrigger=document.getElementById('menuTrigger');
const drawerClose=document.getElementById('drawerClose');
const sidebarToggle=document.getElementById('sidebarToggle');
const sidebarToggleState=sidebarToggle?.querySelector('.sidebar-toggle-state');
function syncSidebarToggle(expanded=false){if(!sidebarToggle)return;sidebarToggle.setAttribute('aria-expanded',String(expanded));if(sidebarToggleState)sidebarToggleState.textContent=expanded?'取消固定':'固定展开'}
const stageNames={1:'第一阶段：先把研究问题想明白',2:'第二阶段：看决定怎样落到项目里',3:'第三阶段：看结果怎样产生并接受复核'};
function buildNav(){
  [1,2,3].forEach(stage=>{
    const block=document.createElement('section');block.className='stage-block';
    const h=document.createElement('h3');h.textContent=stageNames[stage];block.appendChild(h);
    const nav=document.createElement('div');nav.className='chapter-nav-v9';
    chapters.forEach((ch,i)=>{if(ch.stage!==stage)return;const b=document.createElement('button');b.type='button';b.dataset.chapterGo=i;b.innerHTML=`<span>${String(i+1).padStart(2,'0')}</span><b>${ch.title}</b>`;nav.appendChild(b)});block.appendChild(nav);desktopNav.appendChild(block);
    const dh=document.createElement('div');dh.className='drawer-stage';dh.textContent=stageNames[stage];drawerNav.appendChild(dh);
    chapters.forEach((ch,i)=>{if(ch.stage!==stage)return;const b=document.createElement('button');b.type='button';b.dataset.chapterGo=i;b.textContent=`${i+1}. ${ch.title}`;drawerNav.appendChild(b)})
  })
}
function buildStepList(){stepList.innerHTML='';stepNames.forEach((name,i)=>{const b=document.createElement('button');b.type='button';b.dataset.stepGo=i;b.textContent=`${i+1}. ${name}`;if(i===currentStep)b.classList.add('active');stepList.appendChild(b)})}
function parseHash(){const m=location.hash.match(/^#chapter-(\d+)-step-(\d+)$/);if(m)return{chapter:+m[1]-1,step:+m[2]-1};if(location.hash==='#home')return{home:true};if(!location.hash)return null;const c=location.hash.match(/^#chapter-(\d+)$/);if(c)return{chapter:+c[1]-1,step:0};return null}
function updateHash(replace=false){const hash=showingHome?'#home':`#chapter-${currentChapter+1}-step-${currentStep+1}`;try{if(replace)history.replaceState(null,'',hash);else history.pushState(null,'',hash)}catch(e){location.hash=hash}}
function updateProgress(){
  const total=chapters.length*stepNames.length;const done=showingHome?0:currentChapter*stepNames.length+currentStep+1;const pct=Math.round(done/total*100);
  document.getElementById('progressBar').style.width=pct+'%';document.getElementById('progressPercent').textContent=pct+'%';document.getElementById('progressLabel').textContent=showingHome?'尚未开始':`第 ${currentChapter+1} 章 · 第 ${currentStep+1} 步`;
  document.getElementById('sidebarSummary').textContent=showingHome?'课程首页':`${stageNames[chapters[currentChapter].stage]}
第 ${currentChapter+1} 章 · 第 ${currentStep+1} 步`;
}
function updateNav(){document.querySelectorAll('[data-chapter-go]').forEach(b=>{const active=!showingHome&&+b.dataset.chapterGo===currentChapter;b.classList.toggle('active',active);if(active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});buildStepList();updateProgress()}
function showHome(push=true,scroll=true){showingHome=true;homePage.hidden=false;chapterEls.forEach(el=>el.hidden=true);document.body.classList.remove('reading-mode');sidebar?.classList.remove('expanded');syncSidebarToggle(false);updateNav();if(push)updateHash();if(scroll)homePage.scrollIntoView({behavior:'smooth',block:'start'})}
function showLesson(chapter,step,push=true,scroll=true,focus=true){
  currentChapter=Math.max(0,Math.min(chapters.length-1,Number(chapter)));currentStep=Math.max(0,Math.min(stepNames.length-1,Number(step)));showingHome=false;homePage.hidden=true;
  chapterEls.forEach((el,i)=>{const active=i===currentChapter;el.hidden=!active;if(active){el.querySelectorAll('.lesson-step').forEach((s,j)=>{const on=j===currentStep;s.hidden=!on;s.classList.toggle('active',on)});el.querySelectorAll('[data-step-go]').forEach((b,j)=>{const on=j===currentStep;b.classList.toggle('active',on);if(on)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current')});const st=el.querySelector('.step-status');if(st)st.textContent=`第 ${currentStep+1} / ${stepNames.length} 步`;const prev=el.querySelector('[data-prev-step]'),next=el.querySelector('[data-next-step]');prev.disabled=currentChapter===0&&currentStep===0;next.textContent=currentChapter===chapters.length-1&&currentStep===stepNames.length-1?'返回课程首页':(currentStep===stepNames.length-1?'下一章':'下一步')}});
  document.body.classList.toggle('reading-mode',window.scrollY>180);safeStorage.set('crcEvidenceV9Position',JSON.stringify({chapter:currentChapter,step:currentStep}));updateNav();if(push)updateHash();
  const active=chapterEls[currentChapter].querySelector('.lesson-step:not([hidden])');if(scroll)chapterEls[currentChapter].scrollIntoView({behavior:'smooth',block:'start'});if(focus)setTimeout(()=>active?.querySelector('h3')?.focus({preventScroll:true}),50)
}
function nextStep(){if(currentStep<stepNames.length-1)showLesson(currentChapter,currentStep+1);else if(currentChapter<chapters.length-1)showLesson(currentChapter+1,0);else showHome()}
function prevStep(){if(currentStep>0)showLesson(currentChapter,currentStep-1);else if(currentChapter>0)showLesson(currentChapter-1,stepNames.length-1)}
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(window.__toastTimer);window.__toastTimer=setTimeout(()=>el.classList.remove('show'),1900)}
function save(name,text,type='text/plain;charset=utf-8'){const blob=new Blob([text],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),800)}
function downloadResource(key){const resolved=aliases[key]||key;const item=resources[resolved];if(!item){toast('未找到下载资源');return false}save(item.name,item.text,item.type);toast(`已生成：${item.name}`);return true}
async function copyCode(btn){const root=btn.closest('details,.lab-block,.deep-body')||document;const code=root.querySelector('code,pre')?.innerText||'';if(!code){toast('未找到代码');return}try{await navigator.clipboard.writeText(code);toast('代码已复制')}catch(e){const ta=document.createElement('textarea');ta.value=code;document.body.appendChild(ta);ta.select();document.execCommand('copy');ta.remove();toast('代码已复制')}}
function openDrawer(){lastFocus=document.activeElement;drawer.hidden=false;menuTrigger.setAttribute('aria-expanded','true');document.body.style.overflow='hidden';document.querySelector('.course-layout')?.setAttribute('inert','');document.querySelector('.topbar')?.setAttribute('inert','');setTimeout(()=>drawerClose.focus(),0)}
function closeDrawer(){drawer.hidden=true;menuTrigger.setAttribute('aria-expanded','false');document.body.style.overflow='';document.querySelector('.course-layout')?.removeAttribute('inert');document.querySelector('.topbar')?.removeAttribute('inert');(lastFocus||menuTrigger).focus()}
document.addEventListener('click',e=>{
 const home=e.target.closest('[data-home]');if(home){e.preventDefault();showHome();closeDrawerIfOpen();return}
 if(e.target.closest('[data-start]')){showLesson(0,0);return}
 const cg=e.target.closest('[data-chapter-go]');if(cg){showLesson(+cg.dataset.chapterGo,0);closeDrawerIfOpen();return}
 const sg=e.target.closest('[data-step-go]');if(sg){showLesson(currentChapter,+sg.dataset.stepGo);return}
 if(e.target.closest('[data-next-step]')){nextStep();return}if(e.target.closest('[data-prev-step]')){prevStep();return}
 const copy=e.target.closest('.copy');if(copy){copyCode(copy);return}
 const dl=e.target.closest('[data-download]');if(dl){downloadResource(dl.dataset.download);return}
});
function closeDrawerIfOpen(){if(!drawer.hidden)closeDrawer()}
menuTrigger.addEventListener('click',openDrawer);drawerClose.addEventListener('click',closeDrawer);document.getElementById('drawerBackdrop').addEventListener('click',closeDrawer);
sidebarToggle?.addEventListener('click',()=>{if(!document.body.classList.contains('reading-mode'))return;const expanded=sidebar.classList.toggle('expanded');syncSidebarToggle(expanded)});
document.addEventListener('keydown',e=>{if(!drawer.hidden&&e.key==='Tab'){const focusable=[...drawer.querySelectorAll('button:not([disabled]),a[href],[tabindex]:not([tabindex="-1"])')].filter(el=>!el.hidden);if(focusable.length){const first=focusable[0],last=focusable[focusable.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}}if(e.key==='Escape'&&!drawer.hidden)closeDrawer();const arrowBlocked=e.target.closest('button,a,summary,input,textarea,select,[contenteditable="true"],pre,code');if(e.key==='ArrowRight'&&!showingHome&&!arrowBlocked&&!e.altKey&&!e.ctrlKey&&!e.metaKey)nextStep();if(e.key==='ArrowLeft'&&!showingHome&&!arrowBlocked&&!e.altKey&&!e.ctrlKey&&!e.metaKey)prevStep()});
window.addEventListener('popstate',()=>{const p=parseHash();if(!p)return;if(p.home)showHome(false,false);else showLesson(p.chapter,p.step,false,false,false)});
window.addEventListener('hashchange',()=>{const p=parseHash();if(!p)return;if(p.home)showHome(false,false);else showLesson(p.chapter,p.step,false,false,false)});
window.addEventListener('scroll',()=>{if(showingHome)return;const compact=window.scrollY>180;document.body.classList.toggle('reading-mode',compact);if(!compact){sidebar?.classList.remove('expanded');syncSidebarToggle(false)}},{passive:true});
window.addEventListener('beforeprint',()=>{printState={chapters:chapterEls.map(ch=>[ch,ch.hidden]),steps:[],details:[]};chapterEls.forEach(ch=>{ch.hidden=false;ch.querySelectorAll('.lesson-step').forEach(s=>{printState.steps.push([s,s.hidden]);s.hidden=false});ch.querySelectorAll('.deep-layer').forEach(d=>{printState.details.push([d,d.open]);d.open=true})})});
window.addEventListener('afterprint',()=>{(printState.steps||[]).forEach(([el,h])=>el.hidden=h);(printState.details||[]).forEach(([el,o])=>el.open=o);(printState.chapters||[]).forEach(([el,h])=>el.hidden=h)});
syncSidebarToggle(false);
buildNav();
const initial=parseHash();if(initial?.home)showHome(false,false);else if(initial)showLesson(initial.chapter,initial.step,false,false,false);else{let saved=null;try{saved=JSON.parse(safeStorage.get('crcEvidenceV9Position'))}catch(e){}if(saved&&Number.isInteger(saved.chapter)&&Number.isInteger(saved.step))showLesson(saved.chapter,saved.step,false,false,false);else showHome(false,false)}
